using System;
using System.IO;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;

namespace Where_My_Slime.Data
{
    // กรอบการ์ดสกิลตอนต่อสู้ (วงกลมพอร์เทรต + ช่องสกิลสี่เหลี่ยม + หลอด HP + ป้ายเพชร)
    // รูป 366x206 ถูกเจาะช่องด้านในให้โปร่งใสแล้ว (วาดพื้น/พอร์เทรต/หลอดไว้ข้างล่าง แล้ววางกรอบทับ)
    // ถ้ามีไฟล์ UI/Skill_Frame.png ข้างเกม จะใช้ไฟล์นั้นแทนรูปที่ฝังในโค้ด
    public static class SkillFrameArt
    {
        public static Texture2D Frame;

        public const int Width = 366;
        public const int Height = 206;

        // พิกัดต่างๆ บนรูปต้นฉบับ (หน่วยพิกเซลของรูป 366x206)
        public static readonly Vector2 CircleCenter = new Vector2(111.5f, 107f);
        public const float CircleRadius = 70f;
        // ช่องสกิลสี่เหลี่ยมด้านขวาของวงกลม (แสดง Ultimate + ความคืบหน้า SP)
        public static readonly Rectangle SkillSlot = new Rectangle(208, 20, 145, 148);
        // หลอด HP ใต้วงกลมและช่องสกิล
        public static readonly Rectangle HpBar = new Rectangle(52, 183, 300, 13);
        public static readonly Vector2 DiamondCenter = new Vector2(36f, 166f);

        private static readonly string[] Parts =
        {
            "",
            ""
        };

        public static void Load(GraphicsDevice device, Texture2D fromFile)
        {
            if (fromFile != null) { Frame = fromFile; return; }
            try
            {
                byte[] bytes = Convert.FromBase64String(string.Concat(Parts));
                using (var stream = new MemoryStream(bytes))
                {
                    Frame = Texture2D.FromStream(device, stream);
                }
            }
            catch
            {
                Frame = null;
            }
        }
    }
}